/*
 * A339608  Numbers whose bijective base-2 representation is a Lyndon word.
 * https://oeis.org/A339608
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 41, u16 n <= 4720, u32 n <= 9480, u64 n <= 9480,
 *            u128 n <= 9480, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A339608: Numbers whose bijective base‑2 representation is a Lyndon word
 *
 *  The sequence is generated by testing every integer in increasing order for
 *  the property: its bijective base‑2 representation (digits 1 or 2) is a
 *  Lyndon word.  The first term is a(1)=1.
 *
 *  The implementation keeps a static cache of terms so that calls to a(n)
 *  with arbitrary n and in any order are answered in O(1) after the
 *  necessary terms have been generated.  Generating term k requires at most
 *  O(log k) time (to produce and test the base‑2 representation).
 *
 *  The code uses only the operations and constructs allowed by the
 *  specification: arithmetic on seq_t, loops, arrays, and the standard
 *  library headers.  It is valid C11 and C++17 alike.  No <math.h>, no
 *  variable‑length arrays, no designated initializers, no new/class/template
 *  names, and no floating point.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

#define INITIAL_CAP 64

/* static cache of sequence values */
static seq_t *terms = NULL;
static size_t  term_capacity = 0;
static size_t  term_count    = 0;

/* next integer to test (starts at 1) */
static idx_t  next_candidate = 1;

/* ----------------------------------------------------------------------
 *  Utility: test whether an array of digits (1 or 2) is a Lyndon word.
 *  The digits are given in usual most‑significant‑to‑least‑significant
 *  order.  Length 1 is always Lyndon.
 * ---------------------------------------------------------------------- */
static bool is_lyndon(const uint8_t *d, size_t len)
{
    if (len == 1) return true;

    for (size_t shift = 1; shift < len; ++shift) {
        size_t i;
        for (i = 0; i < len; ++i) {
            uint8_t a = d[i];
            uint8_t b = d[(i + shift) % len];

            if (a != b) {
                if (a > b) return false;  /* a rotation is lexicographically smaller */
                break;                     /* rotation larger – continue with next shift */
            }
        }
        if (i == len) return false; /* word equals a non‑trivial rotation */
    }
    return true;
}

/* ----------------------------------------------------------------------
 *  Check whether the bijective base‑2 representation of num is a Lyndon word.
 *  The representation uses digits 1 and 2; conversion is performed by the
 *  standard algorithm: repeatedly decrement, take modulo 2, and divide by 2.
 * ---------------------------------------------------------------------- */
static bool is_bijective_base2_lyndon(seq_t num)
{
    if (num == 0) return false;  /* 0 has no bijective representation */

    /* Temporary buffer for digits – maximum length 64 suffices for the test range. */
    uint8_t digits[64];
    size_t pos = 0;

    seq_t n = num;
    while (n != 0) {
        n = n - 1;                          /* bijective adjustment */
        seq_t r = n % 2;                    /* 0 or 1 */
        digits[pos++] = (uint8_t)( (r & 1) + 1 );  /* convert to 1 or 2 */
        n = n / 2;
        if (pos >= 64) break;               /* safety guard */
    }

    /* digits are currently LSB→MSB; reverse to MSB→LSB */
    for (size_t i = 0; i < pos / 2; ++i) {
        uint8_t tmp = digits[i];
        digits[i]   = digits[pos - 1 - i];
        digits[pos - 1 - i] = tmp;
    }

    return is_lyndon(digits, pos);
}

/* ----------------------------------------------------------------------
 *  Append a new term to the cache, expanding capacity as needed.
 * ---------------------------------------------------------------------- */
static void append_term(seq_t val)
{
    if (term_count >= term_capacity) {
        size_t new_cap = term_capacity ? term_capacity * 2 : INITIAL_CAP;
        terms = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
        term_capacity = new_cap;
    }
    terms[term_count++] = val;
}

/* ----------------------------------------------------------------------
 *  Main function required by the specification.
 * ---------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for n==0 – guard against underflow */

    /* Generate terms until we have at least n of them. */
    while (term_count < n) {
        seq_t cand = (seq_t)next_candidate;
        if (is_bijective_base2_lyndon(cand)) {
            append_term(cand);
        }
        next_candidate++;   /* move to the next integer */
    }

    return terms[n - 1];
}
